import { useState } from "react";

export function Cart({ catalog }) {
  const [items, setItems] = useState([]);          // [{ id, qty }]: the source.
  const [selectedId, setSelectedId] = useState(null); // an id, not a copied object.

  // Derived during render: always in sync.
  const lines = items.map((it) => ({ ...catalog[it.id], qty: it.qty }));
  const total = lines.reduce((sum, l) => sum + l.price * l.qty, 0);
  const count = items.reduce((n, it) => n + it.qty, 0);
  const selected = selectedId ? catalog[selectedId] : null;

  function remove(id) {
    setItems((prev) => prev.filter((it) => it.id !== id));   // total follows automatically.
  }

  return <p>{count} items, total ₹{total}</p>;
}
